%angular
<style>
    .boardCell {
        display: inline-block;
        width: 40px;
        height: 40px;
        border: 1px solid black;
    }

    .blockCell {
        background-color: black;
    }

    .boardContainer {
        line-height: 0;
    }

    .cell {
        position: relative;
        width: 100%;
        height: 100%;
    }

    .cell label {
        position: absolute;
        top: 50%;
        left: 35%;
    }

    .agentJoystick button {
        font-size: 60px;
    }
</style>

<div class="container">
    <div class="row">
        <div class="col-md-6">
            <div class="boardContainer" ng-model="pos">
                <div class="boardRow" ng-repeat="(i, row) in board track by $index">
                    <div class="boardCell" ng-repeat="(j, cell) in row track by $index">
                        <!--Khối tường (1)-->
                        <div class="cell blockCell" ng-if="cell==1"></div>
                        <!--Nhân vật (M)-->
                        <div class="cell" ng-if="i == pos[1] && j == pos[0]"><label>M</label></div>
                        <!--Phần thưởng (C, E, W, G)-->
                        <div class="cell" ng-if="(i != pos[1] || j != pos[0]) && cell != 0 && cell != 1"><label>{{cell}}</label></div>
                        <!--Ô trống-->
                        <div class="cell" ng-if="(i != pos[1] || j != pos[0]) && cell==0"></div>
                    </div>
                </div>
            </div>
        </div>
        <div class="col-md-6">
            <div class="agentJoystick container">
                <div class="row">
                    <div class="col-md-4"></div>
                    <div class="col-md-4"><button ng-click="z.runParagraph('20260223-102900_457825586')">⬆️</button></div>
                    <div class="col-md-4"></div>
                </div>
                <div class="row">
                    <div class="col-md-4"><button ng-click="z.runParagraph('20260223-102922_1678768399')">⬅️</button></div>
                    <div class="col-md-4"></div>
                    <div class="col-md-4"><button ng-click="z.runParagraph('20260223-102929_1861296947')">➡️</button></div>
                </div>
                <div class="row">
                    <div class="col-md-4"></div>
                    <div class="col-md-4"><button ng-click="z.runParagraph('20260223-103003_1557050985')">⬇️</button></div>
                    <div class="col-md-4"></div>
                </div>
            </div>
        </div>
    </div>

    <div class="row">
        <div class="col-md-6">
            <label>Score: {{score}}</label>
        </div>
        <div class="col-md-6">
            <label>Finish: {{finish}}</label>
        </div>
    </div>

    <div class="row">
        <div class="col-md-6">
            <div class="agentJoystick container">
                <button ng-click="z.runParagraph('20260223-102841_1578265359')">🔄</button>
            </div>
        </div>
    </div>
</div>
